% lp2graph canonical LaTeX
% Real-time railway disruption management MILP.
%@ meta id=rail_reschedule family=milp schema=0.1.0
%@ name :: Real-time railway timetable and rolling stock adjustment
%@ desc :: MILP to decide extra carriages and additional stops for trains in response to increased passenger demand caused by disruptions.
%@ index T ordered=0 cyclic=0 :: Set of trains.
%@ index S ordered=0 cyclic=0 :: Set of stations.
%@ param base_demand shape=T,S kind=matrix domain=passengers :: Base passenger demand of train t at station s.
%@ param demand_inc shape=S kind=vector domain=passengers :: Additional passenger demand at station s due to the disruption.
%@ param cost_cap shape=- kind=scalar domain=currency :: Cost per extra carriage.
%@ param cost_stop shape=- kind=scalar domain=currency :: Cost per additional stop.
%@ param base_capacity shape=T kind=vector domain=passengers :: Existing seat capacity of train t.
%@ param cap_per_car shape=- kind=scalar domain=passengers :: Seats provided by one extra carriage.
%@ param max_extra_stops shape=- kind=scalar domain=integer :: Maximum additional stops allowed per train.
%@ param max_extra_cars shape=- kind=scalar domain=integer :: Maximum extra carriages allowed per train.
%@ var extra_cars shape=T domain=integer role=primary drole=- lo=0 hi=- :: Number of extra carriages added to train t.
%@ var y shape=T,S domain=binary role=primary drole=- lo=- hi=- :: Indicator if train t adds a stop at station s.
%@ obj sense=min name=total_cost combination=sum :: Minimize total operational cost (extra carriages + additional stops).
%@ con demand_capacity kind=- domain=- indicator=- :: Ensure capacity covers demand including additional stops.
%@ con stop_limit kind=- domain=- indicator=- :: Limit number of additional stops per train.
%@ con car_limit kind=- domain=- indicator=- :: Limit number of extra carriages per train.
\begin{align}
  \min\quad & \mathit{cost\_cap} \cdot \sum_{t \in \mathcal{T}} \mathit{extra\_cars}_{t}
            + \mathit{cost\_stop} \cdot \sum_{t \in \mathcal{T},\, s \in \mathcal{S}} \mathit{y}_{t,s}
            \tag{total\_cost} \\
  & \sum_{s \in \mathcal{S}} \mathit{base\_demand}_{t,s}
    + \mathit{demand\_inc}_{s} \cdot \mathit{y}_{t,s}
    \le \mathit{base\_capacity}_{t}
    + \mathit{cap\_per\_car} \cdot \mathit{extra\_cars}_{t}
    \qquad \forall t \in \mathcal{T}
    \tag{demand\_capacity} \\
  & \sum_{s \in \mathcal{S}} \mathit{y}_{t,s}
    \le \mathit{max\_extra\_stops}
    \qquad \forall t \in \mathcal{T}
    \tag{stop\_limit} \\
  & \mathit{extra\_cars}_{t}
    \le \mathit{max\_extra\_cars}
    \qquad \forall t \in \mathcal{T}
    \tag{car\_limit}
\end{align}
